"""Author five playable offline games; run after resource_build.py."""
from pack_build_common import *
CAT.extend(json.loads((OUT/'draft-catalog.json').read_text()))
CSS='''*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#111e30;color:#edf2f4;font-family:system-ui,"PingFang SC",sans-serif}body{padding:18px;display:grid;place-items:center}main{width:min(100%,600px)}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h1{font-size:24px;margin:0}p{color:#aebed0;line-height:1.6;font-size:14px;margin:12px 0}button{font:inherit;color:inherit;background:#263b54;border:1px solid #496078;border-radius:12px;min-height:44px;padding:9px 14px;cursor:pointer;touch-action:manipulation}button:focus-visible{outline:3px solid #ffe3a0;outline-offset:2px}button:active{transform:scale(.97)}button:disabled{cursor:default;opacity:.7}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.status{padding:10px 13px;color:#ffe1a0;border-left:3px solid #e8bd66;background:#1b2c42;min-height:44px}#board{margin:16px auto;user-select:none;touch-action:none}small{display:block;color:#8da4b9;font-size:12px;margin-top:14px}.won{border-color:#a7e2b5!important;background:#244b41!important}@media(max-width:420px){body{padding:12px}h1{font-size:21px}p{font-size:13px}button{padding:8px 11px}}'''
def game(slug,title,desc,instructions,html,js,css=''):
 p=make('game',slug,title,desc,['原创','离线','触控'],{'save':False,'orientation':'portrait','layer':'space'})
 put(p,'style.css',CSS+css)
 put(p,'index.html',f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no"><title>{title}</title><link rel="stylesheet" href="style.css"></head><body><main><header><h1>{title}</h1><button id="restart" type="button">新一局</button></header><p>{instructions}</p>{html}<small>完全离线 · 不保存个人数据 · 关闭后本局进度不保留</small></main><script src="game.js"></script></body></html>')
 put(p,'game.js',js)
 put(p,'README.md',f'# {title}\n\n{desc}\n\n## 操作\n\n{instructions}\n\n打开 index.html 可直接试玩，或在小伴游戏空间手动导入整个 ZIP。支持鼠标/触摸；方向类游戏同时支持键盘。新一局会重新开始，不联网、不收集数据、不写本地存储。\n\n## 许可\n\n原创游戏，代码及几何图形 MIT。\n')
 # Purpose-built SVG cover, text assets only as required by desktop importer.
 icons={'memory-orchard':'<rect x="340" y="90" width="110" height="150" rx="16" fill="#dbaf68"/><rect x="470" y="110" width="110" height="150" rx="16" fill="#7ac1b7"/><text x="395" y="190" text-anchor="middle" font-size="55">✦</text><text x="525" y="210" text-anchor="middle" font-size="55">✦</text>', 'signal-garden':''.join(f'<rect x="{340+x*48}" y="{90+y*48}" width="38" height="38" rx="7" fill="{["#e5bf72","#253a54"][(x+y)%2]}"/>' for x in range(4) for y in range(4)), 'pocket-labyrinth':'<path d="M350 100H570V260H350V100M390 100V210H530V140H440V175" fill="none" stroke="#8ccfc1" stroke-width="18"/><circle cx="390" cy="260" r="12" fill="#f4cd7b"/>','tile-harbor':''.join(f'<rect x="{350+x*65}" y="{90+y*65}" width="55" height="55" rx="8" fill="#365976"/><text x="{377+x*65}" y="{125+y*65}" text-anchor="middle" font-size="25" fill="#f2d291">{1+x+3*y}</text>' for x in range(3) for y in range(3) if x+3*y<8),'starlight-catcher':'<rect x="350" y="260" width="140" height="18" rx="9" fill="#83c8c2"/><circle cx="400" cy="125" r="20" fill="#f4c36f"/><circle cx="530" cy="180" r="20" fill="#ac8bcb"/><circle cx="460" cy="70" r="12" fill="#f4c36f"/>'}
 put(p,'cover.svg',f'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360" viewBox="0 0 640 360"><rect width="640" height="360" rx="24" fill="#142439"/><text x="44" y="130" fill="#f1d193" font-size="20" font-family="sans-serif">离线小游戏</text><text x="44" y="184" fill="#eef1ef" font-size="30" font-family="sans-serif">{title}</text><text x="44" y="230" fill="#9cb1c2" font-size="16" font-family="sans-serif">原创 · 鼠标 / 触控</text>{icons[slug]}</svg>')
 return p
game('memory-orchard','记忆果园','翻开成对几何果实，16张卡片组成的离线记忆小游戏。','点击两张卡找出相同图案；不匹配会稍后翻回。配齐8对获胜，没有限时。', '<div id="status" class="status" role="status" aria-live="polite"></div><div id="board" aria-label="记忆卡片"></div>', r'''(()=>{
const board=document.querySelector('#board'),status=document.querySelector('#status');const faces=['◉','✦','▲','◆','☀','☾','●','✿'];let selected=[],matched=0,moves=0,locked=false,timer;
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function info(){status.textContent=`已配对 ${matched}/8 · 翻牌 ${moves} 次${matched===8?' · 全部找到了！':''}`;status.classList.toggle('won',matched===8)}
function choose(b){if(locked||b.dataset.matched==='true'||selected.includes(b))return;b.textContent=faces[Number(b.dataset.value)];b.classList.add('open');b.setAttribute('aria-label',`图案 ${Number(b.dataset.value)+1}`);selected.push(b);if(selected.length===2){moves++;locked=true;const[a,c]=selected;if(a.dataset.value===c.dataset.value){a.dataset.matched=c.dataset.matched='true';a.disabled=c.disabled=true;matched++;selected=[];locked=false;info()}else{info();timer=setTimeout(()=>{for(const x of selected){x.textContent='?';x.classList.remove('open');x.setAttribute('aria-label','未翻开的卡片')}selected=[];locked=false},700)}}}
function reset(){clearTimeout(timer);selected=[];matched=0;moves=0;locked=false;board.replaceChildren();shuffle([...Array(8).keys(),...Array(8).keys()]).forEach((v,i)=>{const b=document.createElement('button');b.type='button';b.textContent='?';b.dataset.value=v;b.dataset.index=i;b.setAttribute('aria-label',`未翻开的卡片 ${i+1}`);b.addEventListener('click',()=>choose(b));board.append(b)});info()}
document.querySelector('#restart').onclick=reset;reset();
})();''', '#board{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:430px}#board button{aspect-ratio:1;font-size:clamp(25px,7vw,43px);padding:0;background:linear-gradient(145deg,#29455e,#20344c);color:#efd494}#board button.open{background:#e2c58c;color:#19304a}#board button[data-matched=true]{background:#34625e;color:#c5e9d5;opacity:1}')
game('signal-garden','信号花园','切换十字邻格，让16盏灯全部熄灭；每局都由可解步骤生成。','点一格会切换自己和上下左右四格。让所有灯熄灭；需要时点提示查看下一步。','<div id="status" class="status" role="status" aria-live="polite"></div><div class="toolbar"><button id="hint" type="button">给我一步提示</button></div><div id="board" aria-label="灯格棋盘"></div>',r'''(()=>{
const board=document.querySelector('#board'),status=document.querySelector('#status');let cells=[],moves=0,solution=new Set(),hint=-1;
function toggle(i){const x=i%4,y=Math.floor(i/4);for(const [dx,dy] of [[0,0],[1,0],[-1,0],[0,1],[0,-1]]){let a=x+dx,b=y+dy;if(a>=0&&a<4&&b>=0&&b<4)cells[b*4+a]=!cells[b*4+a]}}
function draw(){const won=cells.every(v=>!v);status.textContent=won?`花园安静了 · 用了 ${moves} 步`:`还亮着 ${cells.filter(Boolean).length} 盏 · 已走 ${moves} 步`;status.classList.toggle('won',won);board.replaceChildren();cells.forEach((v,i)=>{const b=document.createElement('button');b.type='button';b.dataset.index=i;b.dataset.lit=String(v);b.className=(v?'lit ':'')+(hint===i?'hint':'');b.textContent=v?'●':'○';b.setAttribute('aria-label',`第${Math.floor(i/4)+1}行第${i%4+1}列，${v?'亮':'灭'}${hint===i?'，提示位置':''}`);b.disabled=won;b.onclick=()=>{toggle(i);solution.has(i)?solution.delete(i):solution.add(i);moves++;hint=-1;draw()};board.append(b)})}
function reset(){cells=Array(16).fill(false);solution=new Set();moves=0;hint=-1;for(let i=0;i<8;i++){const n=Math.floor(Math.random()*16);toggle(n);solution.has(n)?solution.delete(n):solution.add(n)}if(cells.every(v=>!v)){toggle(0);solution.add(0)}draw()}
document.querySelector('#hint').onclick=()=>{hint=solution.values().next().value??-1;draw()};document.querySelector('#restart').onclick=reset;reset();})();''','#board{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:400px}#board button{aspect-ratio:1;font-size:30px;color:#7b94a5;background:#1b3046}#board .lit{background:#dec07c;color:#fff6d5;box-shadow:0 0 18px #edc66d25}#board .hint{outline:3px dashed #b5eddf;outline-offset:2px}')
game('pocket-labyrinth','口袋迷径','随机生成一张可通行迷宫，收集三颗星后抵达出口。','方向键、WASD或下方按钮移动。先找到3颗星，再到右下角旗帜；每一局都可走通。','<div id="status" class="status" role="status" aria-live="polite"></div><div id="board" aria-label="迷宫"></div><div class="dpad"><button data-dir="up" aria-label="向上">↑</button><button data-dir="left" aria-label="向左">←</button><button data-dir="down" aria-label="向下">↓</button><button data-dir="right" aria-label="向右">→</button></div>',r'''(()=>{
const board=document.querySelector('#board'),status=document.querySelector('#status');const N=19,dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};let map=[],x=1,y=1,stars=new Set(),steps=0,finished=false;
function carve(cx,cy){map[cy*N+cx]=0;let ds=[[2,0],[-2,0],[0,2],[0,-2]].sort(()=>Math.random()-.5);for(const[dx,dy]of ds){let a=cx+dx,b=cy+dy;if(a>0&&a<N-1&&b>0&&b<N-1&&map[b*N+a]){map[(cy+dy/2)*N+cx+dx/2]=0;carve(a,b)}}}
function draw(){board.replaceChildren();map.forEach((v,i)=>{const c=document.createElement('span');c.dataset.x=i%N;c.dataset.y=Math.floor(i/N);c.dataset.wall=v;c.className=v?'wall':'path';if(i===y*N+x){c.classList.add('player');c.textContent='●'}else if(stars.has(i)){c.classList.add('star');c.textContent='✦'}else if(i===(N-2)*N+N-2){c.classList.add('exit');c.textContent='⚑'}board.append(c)});status.textContent=finished?`走出迷径！共 ${steps} 步`:`已收集 ${3-stars.size}/3 颗星 · ${steps} 步`;status.classList.toggle('won',finished);board.dataset.player=`${x},${y}`}
function move(dir){if(finished)return;const d=dirs[dir];let a=x+d[0],b=y+d[1];if(a<0||a>=N||b<0||b>=N||map[b*N+a])return;x=a;y=b;steps++;stars.delete(y*N+x);if(x===N-2&&y===N-2&&stars.size===0)finished=true;draw()}
function reset(){map=Array(N*N).fill(1);carve(1,1);x=y=1;steps=0;finished=false;const open=map.map((v,i)=>v?-1:i).filter(i=>i>=0&&i!==N+1&&i!==(N-2)*N+N-2);stars=new Set();while(stars.size<3)stars.add(open[Math.floor(Math.random()*open.length)]);draw()}
const key={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};window.addEventListener('keydown',e=>{if(key[e.key]){e.preventDefault();move(key[e.key])}});document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>move(b.dataset.dir));document.querySelector('#restart').onclick=reset;reset();})();''','#board{display:grid;grid-template-columns:repeat(19,1fr);gap:0;width:min(100%,390px);aspect-ratio:1;background:#183146;border:7px solid #34566c;border-radius:12px;overflow:hidden}#board span{display:grid;place-items:center;line-height:1;font-size:clamp(8px,2vw,16px)}.wall{background:#34566c}.path{background:#15283b}.player{color:#a4e7d3}.star{color:#f5c862}.exit{color:#e6f4ef}.dpad{display:grid;grid-template-columns:repeat(3,65px);justify-content:center;gap:7px}.dpad button:first-child{grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}')
game('tile-harbor','方块归港','通过相邻滑动还原数字次序，支持3×3与4×4两种棋盘。','点击空格旁的数字移动它。将数字按从左到右、从上到下排列，空格留在右下角。洗牌只用合法移动，保证可解。','<div class="toolbar"><button id="small">3 × 3</button><button id="large">4 × 4</button></div><div id="status" class="status" role="status" aria-live="polite"></div><div id="board" aria-label="滑块棋盘"></div>',r'''(()=>{
const board=document.querySelector('#board'),status=document.querySelector('#status');let n=3,tiles=[],blank=8,moves=0,finished=false;
function neighbors(i){let x=i%n,y=Math.floor(i/n);return [[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&a<n&&b>=0&&b<n).map(([a,b])=>b*n+a)}
function solved(){return tiles.every((v,i)=>v===(i+1)%(n*n))}
function draw(){board.style.gridTemplateColumns=`repeat(${n},1fr)`;board.replaceChildren();tiles.forEach((v,i)=>{const b=document.createElement('button');b.type='button';b.textContent=v||'';b.dataset.index=i;b.dataset.value=v;b.className=v?'':'blank';b.setAttribute('aria-label',v?`数字 ${v}`:'空格');b.disabled=!v||finished;b.onclick=()=>{if(!neighbors(blank).includes(i))return;[tiles[i],tiles[blank]]=[tiles[blank],tiles[i]];blank=i;moves++;finished=solved();draw()};board.append(b)});status.textContent=finished?`全部归位！用了 ${moves} 步`:`${n} × ${n} · 已移动 ${moves} 步`;status.classList.toggle('won',finished)}
function reset(size=n){n=size;tiles=Array.from({length:n*n},(_,i)=>(i+1)%(n*n));blank=n*n-1;moves=0;finished=false;let previous=-1;for(let i=0;i<(n===3?26:70);i++){let choices=neighbors(blank).filter(v=>v!==previous);const next=choices[Math.floor(Math.random()*choices.length)];previous=blank;[tiles[blank],tiles[next]]=[tiles[next],tiles[blank]];blank=next}if(solved()){let i=neighbors(blank)[0];[tiles[i],tiles[blank]]=[tiles[blank],tiles[i]];blank=i}draw()}
document.querySelector('#restart').onclick=()=>reset();document.querySelector('#small').onclick=()=>reset(3);document.querySelector('#large').onclick=()=>reset(4);reset();})();''','#board{display:grid;gap:9px;max-width:400px;background:#1b3047;padding:10px;border-radius:16px}#board button{aspect-ratio:1;font-size:clamp(22px,7vw,39px);background:#31516b;color:#f3d39a;box-shadow:0 4px 0 #0e2336}#board .blank{background:#111e30;border-color:transparent;box-shadow:none;opacity:1}')
game('starlight-catcher','接住星光','移动接盘收集金色星光，避开紫色碎片，15颗即赢一局。','点击“开始”后，左右拖动或用方向键移动接盘。接住金色圆点加1分，紫色碎片或漏掉星光减1颗心，收集15颗获胜。','<div id="status" class="status" role="status" aria-live="polite"></div><div class="toolbar"><button id="start">开始</button><button id="pause">暂停</button></div><canvas id="board" width="360" height="420" aria-label="接星光游戏画布"></canvas><div class="toolbar"><button id="left" aria-label="向左移动">← 按住向左</button><button id="right" aria-label="向右移动">按住向右 →</button></div>',r'''(()=>{
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),status=document.querySelector('#status');let paddle=180,drops=[],score=0,lives=5,running=false,started=false,ended=false,clock=0,spawn=0,last=0,dir=0,raf=0;
function info(){status.textContent=ended?(score>=15?'收齐星光，挑战成功！':`本局结束 · 收到 ${score} 颗，点新一局再试`):`${started?(running?'收集中':'已暂停'):'准备好再开始'} · 星光 ${score}/15 · 剩余 ${lives} 颗心`;status.dataset.score=score;status.dataset.lives=lives;status.dataset.paddle=Math.round(paddle);status.classList.toggle('won',score>=15)}
function draw(){ctx.clearRect(0,0,360,420);const g=ctx.createLinearGradient(0,0,0,420);g.addColorStop(0,'#15253b');g.addColorStop(1,'#0c1727');ctx.fillStyle=g;ctx.fillRect(0,0,360,420);ctx.fillStyle='#5b759144';for(let i=0;i<28;i++)ctx.fillRect((i*137)%360,(i*83)%350,2,2);for(const d of drops){ctx.beginPath();ctx.arc(d.x,d.y,d.bad?10:8,0,Math.PI*2);ctx.fillStyle=d.bad?'#af8bc9':'#f2c767';ctx.shadowBlur=14;ctx.shadowColor=ctx.fillStyle;ctx.fill();ctx.shadowBlur=0}ctx.fillStyle='#8ed9c7';ctx.beginPath();ctx.roundRect(paddle-36,383,72,13,6);ctx.fill();if(!started){ctx.fillStyle='#cfdfeb';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText('金色留下，紫色躲开',180,200)}}
function frame(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;if(running){clock+=dt;spawn-=dt;paddle=Math.max(36,Math.min(324,paddle+dir*240*dt));if(spawn<=0){drops.push({x:25+Math.random()*310,y:-15,bad:Math.random()<.23});spawn=Math.max(.4,.9-score*.025)}for(const d of drops){d.y+=(85+score*3)*dt;if(d.y>=375&&d.y<=400&&Math.abs(d.x-paddle)<42){if(d.bad)lives--;else score++;d.y=500}else if(d.y>420&&!d.bad){lives--;d.y=500}}drops=drops.filter(d=>d.y<450);if(lives<=0||score>=15){running=false;ended=true;lives=Math.max(0,lives)}info()}draw();raf=requestAnimationFrame(frame)}
function reset(){paddle=180;drops=[];score=0;lives=5;running=false;started=false;ended=false;clock=spawn=0;dir=0;info();draw()}
function aim(e){const r=canvas.getBoundingClientRect();paddle=Math.max(36,Math.min(324,(e.clientX-r.left)*360/r.width));info()}
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);aim(e)});canvas.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='touch')aim(e)});window.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();dir=e.key==='ArrowLeft'?-1:1}});window.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight')dir=0});window.addEventListener('blur',()=>{running=false;dir=0;info()});for(const [id,value]of [['left',-1],['right',1]]){const b=document.querySelector('#'+id);b.addEventListener('pointerdown',e=>{b.setPointerCapture(e.pointerId);dir=value});b.addEventListener('pointerup',()=>dir=0);b.addEventListener('pointercancel',()=>dir=0)}
document.querySelector('#start').onclick=()=>{if(ended)reset();started=true;running=true;info()};document.querySelector('#pause').onclick=()=>{if(!started||ended)return;running=!running;info()};document.querySelector('#restart').onclick=reset;reset();raf=requestAnimationFrame(frame);})();''','canvas{display:block;width:min(100%,360px);height:auto;border:1px solid #3d5269;border-radius:16px;touch-action:none}.toolbar button{flex:1}')
